import { useAuth } from "@/_core/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { addMember as addMemberSupabase, createAnnouncement as createAnnouncementSupabase, createWithdrawal as createWithdrawalSupabase, deleteMember as deleteMemberSupabase, deletePayment as deletePaymentSupabase, updatePayment as updatePaymentSupabase, deleteWithdrawal as deleteWithdrawalSupabase, loadFamily, previewPayment as previewPaymentSupabase, recordGroupPayments as recordGroupPaymentsSupabase, recordPayment as recordPaymentSupabase, updateContribution as updateContributionSupabase, updateMember as updateMemberSupabase } from "@/lib/familySupabase";
import {
  ArrowDownLeft,
  ArrowUpRight,
  BarChart3,
  CalendarDays,
  Check,
  ChevronDown,
  CircleAlert,
  ClipboardList,
  Download,
  FileText,
  Landmark,
  Loader2,
  Megaphone,
  Pencil,
  Plus,
  Receipt,
  RefreshCw,
  Search,
  Trash2,
  ShieldCheck,
  Sparkles,
  TrendingUp,
  UserPlus,
  Users,
  Wallet,
  X,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";
import { toast } from "sonner";

const monthNames = ["Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Août", "Sep", "Oct", "Nov", "Déc"];
const categories = ["SANTE", "URGENCE", "DECES", "EDUCATION", "EVENEMENT_FAMILIAL", "AIDE_FAMILIALE", "DEPLACEMENT", "AUTRE"] as const;
const methods = ["ESPECES", "MOBILE_MONEY", "VIREMENT", "CHEQUE"];
function sortableDate(value: unknown) { if (!value) return 0; if (value instanceof Date) return value.getTime() || 0; const raw = String(value).trim(); const european = raw.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/); if (european) return new Date(Number(european[3]), Number(european[2]) - 1, Number(european[1])).getTime(); const time = Date.parse(raw); return Number.isNaN(time) ? 0 : time; }
function recordTimestamp(record: any) { return sortableDate(record.createdAt ?? record.created_at) || Number(record.id ?? 0); }

type Category = (typeof categories)[number];

function currency(value: number | undefined) {
  return `${new Intl.NumberFormat("fr-FR").format(value ?? 0)} FCFA`;
}
function shortCurrency(value: number | undefined) {
  const amount = value ?? 0;
  if (amount >= 1000000) return `${(amount / 1000000).toFixed(1)} M`;
  if (amount >= 1000) return `${Math.round(amount / 1000)} k`;
  return new Intl.NumberFormat("fr-FR").format(amount);
}
function dateForApi(value: string) {
  return new Date(`${value}T12:00:00.000Z`).toISOString();
}
function currentMonth() {
  const now = new Date();
  return `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, "0")}`;
}
function monthInputLabel(value: string) {
  const [year, month] = value.split("-").map(Number);
  return `${monthNames[(month ?? 1) - 1]} ${year}`;
}
function initials(name: string) {
  return name.split(" ").slice(0, 2).map((part) => part[0]).join("").toUpperCase();
}
function statusLabel(status: string) {
  if (status === "RETARD") return { label: "En retard", className: "bg-[#fff0ef] text-[#b94d43]" };
  if (status === "AVANCE") return { label: "En avance", className: "bg-[#edf3f1] text-[#23734c]" };
  return { label: "À jour", className: "bg-[#eef5cb] text-[#4f681f]" };
}
function isoToDateInput(value?: string | Date) {
  const date = value ? new Date(value) : new Date();
  return date.toISOString().slice(0, 10);
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-2 text-[11px] font-bold uppercase tracking-[0.18em] text-[#7c9487]">{eyebrow}</p><h1 className="text-3xl font-semibold tracking-[-0.03em] text-[#243447] sm:text-[38px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#718078]">{description}</p>}</div>{action}</div>;
}
function MetricCard({ label, value, meta, icon: Icon, tone = "mint" }: { label: string; value: string; meta: string; icon: typeof Wallet; tone?: "mint" | "lime" | "warm" | "plain" }) {
  const colors = { mint: "bg-[#e4f2e9] text-[#285d68]", lime: "bg-[#f2c766] text-[#243447]", warm: "bg-[#fff0d9] text-[#9a631e]", plain: "bg-white text-[#285d68]" };
  return <div className="rounded-2xl border border-[#e5ded2] bg-white p-5 shadow-[0_12px_40px_-30px_rgba(18,66,52,0.45)]"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-medium text-[#7b8589]">{label}</p><p className="mt-3 text-[25px] font-semibold tracking-[-0.04em] text-[#243447]">{value}</p></div><div className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${colors[tone]}`}><Icon className="h-[18px] w-[18px]" /></div></div><p className="mt-4 text-xs text-[#789085]">{meta}</p></div>;
}
function StatusBadge({ status }: { status: string }) { const item = statusLabel(status); return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold ${item.className}`}>{item.label}</span>; }
function EmptyState({ icon: Icon, title, body }: { icon: typeof FileText; title: string; body: string }) { return <div className="rounded-2xl border border-dashed border-[#cad8cd] bg-[#fbfcfa] px-6 py-12 text-center"><div className="mx-auto grid h-11 w-11 place-items-center rounded-2xl bg-[#e8f1e9] text-[#285d68]"><Icon className="h-5 w-5" /></div><p className="mt-4 text-sm font-semibold text-[#243447]">{title}</p><p className="mx-auto mt-1 max-w-sm text-sm leading-6 text-[#819087]">{body}</p></div>; }

export default function Home() {
  const { user } = useAuth();
  const [location] = useLocation();
  const [period, setPeriod] = useState(currentMonth);
  const [data, setData] = useState<any>(null);
  const [snapshotLoading, setSnapshotLoading] = useState(true);
  const [snapshotError, setSnapshotError] = useState<Error | null>(null);
  const reload = async () => { if (!user) return; setSnapshotLoading(true); try { setData(await loadFamily(period)); setSnapshotError(null); } catch (error) { setSnapshotError(error as Error); } finally { setSnapshotLoading(false); } };
  useEffect(() => { void reload(); }, [user?.openId, period]);
  const admin = user?.role === "admin";

  const [memberOpen, setMemberOpen] = useState(false);
  const [editingMemberId, setEditingMemberId] = useState<number | null>(null);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [editingPaymentId, setEditingPaymentId] = useState<number | null>(null);
  const [groupOpen, setGroupOpen] = useState(false);
  const [withdrawalOpen, setWithdrawalOpen] = useState(false);
  const [announcementOpen, setAnnouncementOpen] = useState(false);
  const [paymentPreviewData, setPaymentPreviewData] = useState<any>(null);
  const [paymentPreviewLoading, setPaymentPreviewLoading] = useState(false);
  const [memberSearch, setMemberSearch] = useState("");
  const [memberSort, setMemberSort] = useState<"alpha" | "alphaDesc" | "recent" | "oldest">("alpha");
  const [selectedGroupMembers, setSelectedGroupMembers] = useState<string[]>([]);
  const [memberForm, setMemberForm] = useState({ fullName: "", phone: "", email: "", joinedAt: isoToDateInput(), notes: "" });
  const [paymentForm, setPaymentForm] = useState({ memberId: "", amount: "1000", paymentDate: isoToDateInput(), paymentMethod: "ESPECES", reference: "", observation: "" });
  const [groupForm, setGroupForm] = useState({ month: period, paymentDate: isoToDateInput(), paymentMethod: "ESPECES" });
  const [withdrawalForm, setWithdrawalForm] = useState<{ withdrawalDate: string; amount: string; category: Category; beneficiary: string; motif: string; description: string; paymentMethod: string; reference: string; observation: string }>({ withdrawalDate: isoToDateInput(), amount: "", category: "SANTE", beneficiary: "", motif: "", description: "", paymentMethod: "ESPECES", reference: "", observation: "" });
  const [announcementForm, setAnnouncementForm] = useState({ title: "", body: "" });
  const [contributionDraft, setContributionDraft] = useState("");

  const action = (operation: (input: any) => Promise<any>, success: () => void) => ({ isPending: false, mutate: (input: any) => { void operation(input).then(success).catch((error) => toast.error(error.message)); } });
  const addMember = action(addMemberSupabase, () => { toast.success("Membre ajouté"); setMemberOpen(false); void reload(); });
  const updateMember = action(updateMemberSupabase, () => { toast.success("Membre modifié"); setMemberOpen(false); setEditingMemberId(null); void reload(); });
  const deleteMember = action(deleteMemberSupabase, () => { toast.success("Membre supprimé"); void reload(); });
  const recordPayment = action(recordPaymentSupabase, () => { toast.success("Paiement enregistré et affecté"); setPaymentOpen(false); setPaymentPreviewData(null); void reload(); });
  const deletePayment = action(deletePaymentSupabase, () => { toast.success("Paiement annulé"); void reload(); });
  const updatePayment = action(updatePaymentSupabase, () => { toast.success("Paiement modifié"); setPaymentOpen(false); setEditingPaymentId(null); setPaymentPreviewData(null); void reload(); });
  const bulkDeletePayments = async (ids: number[]) => { await Promise.all(ids.map((id) => deletePaymentSupabase({ id }))); toast.success(`${ids.length} paiement(s) annulé(s)`); await reload(); };
  const bulkUpdatePayments = async (ids: number[], amount: number) => { await Promise.all(ids.map((id) => updatePaymentSupabase({ id, amount }))); toast.success(`${ids.length} paiement(s) corrigé(s)`); await reload(); };
  const recordGroupPayments = action(recordGroupPaymentsSupabase, () => { toast.success("Paiements groupés enregistrés"); setGroupOpen(false); setSelectedGroupMembers([]); void reload(); });
  const createWithdrawal = action(createWithdrawalSupabase, () => { toast.success("Sortie enregistrée"); setWithdrawalOpen(false); void reload(); });
  const deleteWithdrawal = action(deleteWithdrawalSupabase, () => { toast.success("Sortie supprimée"); void reload(); });
  const createAnnouncement = action(createAnnouncementSupabase, () => { toast.success("Annonce publiée"); setAnnouncementOpen(false); void reload(); });
  const updateContribution = action(updateContributionSupabase, () => { toast.success("Cotisation mensuelle mise à jour"); void reload(); });

  if (snapshotLoading) return <div className="grid min-h-[70vh] place-items-center"><div className="flex items-center gap-3 text-sm text-[#718078]"><Loader2 className="h-5 w-5 animate-spin text-[#285d68]" />Chargement de la caisse…</div></div>;
  if (snapshotError) return <div className="rounded-2xl border border-[#f2d4d0] bg-[#fff8f7] p-6 text-[#9a4942]">Impossible de charger les données. {snapshotError.message}</div>;

  const summary = data?.summary;
  const members: any[] = data?.members ?? [];
  const activeMembers: any[] = members.filter((member) => member.isActive);
  const filteredMembers = members.filter((member) => member.fullName.toLowerCase().includes(memberSearch.toLowerCase()) || member.phone?.includes(memberSearch));
  const page = location === "/" ? "dashboard" : location.slice(1);
  const titleByPage: Record<string, string> = { dashboard: "Bonjour, la caisse avance.", members: "Les membres", contributions: "Cotisations", cash: "La caisse commune", history: "Historique des paiements", reports: "Rapports mensuels", statistics: "Statistiques", announcements: "Annonces familiales", audit: "Journal d’audit", settings: "Paramètres" };

  const refreshButton = <Button variant="outline" onClick={() => reload()} className="h-10 rounded-xl border-[#d8ccba] bg-white text-[#446356] hover:bg-[#eef5ef]"><RefreshCw className="mr-2 h-4 w-4" />Actualiser</Button>;
  const openPayment = (memberId?: string) => { setEditingPaymentId(null); setPaymentForm((form) => ({ ...form, memberId: memberId ?? form.memberId, amount: String(data?.contribution ?? 1000) })); setPaymentPreviewData(null); setPaymentOpen(true); };
  const openPaymentEdit = (payment: any) => { setEditingPaymentId(Number(payment.id)); setPaymentForm((form) => ({ ...form, memberId: String(payment.memberId ?? payment.member_id ?? ""), amount: String(payment.amount ?? ""), paymentDate: isoToDateInput(payment.paymentDate ?? payment.payment_date), reference: payment.reference ?? "", observation: "" })); setPaymentPreviewData({ allocation: [], memberName: payment.memberName, contribution: data?.contribution }); setPaymentOpen(true); };
  const openMemberEdit = (member: any) => { setEditingMemberId(member.memberId); setMemberForm({ fullName: member.fullName ?? "", phone: member.phone ?? "", email: member.email ?? "", joinedAt: isoToDateInput(member.joinedAt), notes: member.notes ?? "" }); setMemberOpen(true); };
  const submitPaymentPreview = async () => { const amount = Number(paymentForm.amount); const memberId = paymentForm.memberId; if (!memberId || !Number.isInteger(amount) || amount <= 0) return toast.error("Sélectionnez un membre et un montant positif."); setPaymentPreviewLoading(true); try { setPaymentPreviewData(await previewPaymentSupabase(memberId, amount, dateForApi(paymentForm.paymentDate))); } catch (error) { toast.error((error as Error).message); } finally { setPaymentPreviewLoading(false); } };
  const confirmPayment = () => { if (editingPaymentId) { updatePayment.mutate({ id: editingPaymentId, amount: Number(paymentForm.amount), paymentDate: dateForApi(paymentForm.paymentDate), reference: paymentForm.reference || undefined }); return; } if (!paymentPreviewData) return toast.error("Prévisualisez l'affectation avant de confirmer."); recordPayment.mutate({ memberId: paymentForm.memberId, amount: Number(paymentForm.amount), paymentDate: dateForApi(paymentForm.paymentDate), paymentMethod: paymentForm.paymentMethod, reference: paymentForm.reference || undefined, observation: paymentForm.observation || undefined }); };

  return <>
    {page === "dashboard" && <DashboardPage data={data} period={period} setPeriod={setPeriod} admin={admin} openPayment={openPayment} openGroup={() => { setGroupForm((form) => ({ ...form, month: period })); setGroupOpen(true); }} openWithdrawal={() => setWithdrawalOpen(true)} refreshButton={refreshButton} />}
    {page === "members" && <MembersPage members={filteredMembers} search={memberSearch} setSearch={setMemberSearch} sort={memberSort} setSort={setMemberSort} admin={admin} openPayment={openPayment} openMember={() => { setEditingMemberId(null); setMemberForm({ fullName: "", phone: "", email: "", joinedAt: isoToDateInput(), notes: "" }); setMemberOpen(true); }} editMember={openMemberEdit} deleteMember={(id, name) => { if (window.confirm(`Supprimer définitivement le membre « ${name} » ? Cette action peut être refusée s’il possède déjà des paiements.`)) deleteMember.mutate({ id }); }} />}
    {page === "contributions" && <ContributionsPage data={data} period={period} setPeriod={setPeriod} admin={admin} openPayment={openPayment} openGroup={() => { setGroupForm((form) => ({ ...form, month: period })); setGroupOpen(true); }} editPayment={openPaymentEdit} deletePayment={(id, name, amount) => { if (window.confirm(`Annuler le paiement de ${currency(amount)} enregistré pour ${name} ? Les mois affectés seront libérés.`)) deletePayment.mutate({ id }); }} />}
    {page === "cash" && <CashPage data={data} admin={admin} openWithdrawal={() => setWithdrawalOpen(true)} deleteWithdrawal={(id) => { if (window.confirm("Supprimer définitivement cette sortie ?")) deleteWithdrawal.mutate({ id }); }} />}
    {page === "history" && <HistoryPage data={data} admin={admin} editPayment={openPaymentEdit} bulkDeletePayments={bulkDeletePayments} bulkUpdatePayments={bulkUpdatePayments} deletePayment={(id, name, amount) => { if (window.confirm(`Annuler le paiement de ${currency(amount)} enregistré pour ${name} ? Les mois affectés seront libérés.`)) deletePayment.mutate({ id }); }} />}
    {page === "reports" && <ReportsPage data={data} />}
    {page === "statistics" && <StatisticsPage data={data} />}
    {page === "status" && <StatusPage data={data} />}
    {page === "announcements" && <AnnouncementsPage data={data} admin={admin} openAnnouncement={() => setAnnouncementOpen(true)} />}
    {page === "audit" && <AuditPage data={data} />}
    {page === "settings" && <SettingsPage data={data} admin={admin} draft={contributionDraft || String(data?.contribution ?? "")} setDraft={setContributionDraft} save={() => updateContribution.mutate({ amount: Number(contributionDraft || data?.contribution || 0) })} />}
    {!["dashboard", "members", "contributions", "cash", "history", "reports", "statistics", "status", "announcements", "audit", "settings"].includes(page) && <DashboardPage data={data} period={period} setPeriod={setPeriod} admin={admin} openPayment={openPayment} openGroup={() => setGroupOpen(true)} openWithdrawal={() => setWithdrawalOpen(true)} refreshButton={refreshButton} />}

    <Dialog open={memberOpen} onOpenChange={(open) => { setMemberOpen(open); if (!open) setEditingMemberId(null); }}><DialogContent><DialogHeader><DialogTitle>{editingMemberId ? "Modifier un membre" : "Ajouter un membre"}</DialogTitle><DialogDescription>Le membre rejoindra automatiquement les échéances à partir de sa date d’adhésion.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><Field label="Nom complet"><Input value={memberForm.fullName} onChange={(e) => setMemberForm({ ...memberForm, fullName: e.target.value })} placeholder="Ex. Jean Kouassi" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Téléphone"><Input value={memberForm.phone} onChange={(e) => setMemberForm({ ...memberForm, phone: e.target.value })} placeholder="+225 …" /></Field><Field label="E-mail"><Input type="email" value={memberForm.email} onChange={(e) => setMemberForm({ ...memberForm, email: e.target.value })} placeholder="jean@email.com" /></Field></div><Field label="Date d’adhésion"><Input type="date" value={memberForm.joinedAt} onChange={(e) => setMemberForm({ ...memberForm, joinedAt: e.target.value })} /></Field><Field label="Note (optionnel)"><Textarea value={memberForm.notes} onChange={(e) => setMemberForm({ ...memberForm, notes: e.target.value })} /></Field></div><DialogFooter><Button variant="outline" onClick={() => setMemberOpen(false)}>Annuler</Button>{editingMemberId ? <Button disabled={updateMember.isPending} className="bg-[#285d68] text-white hover:bg-[#214e58]" onClick={() => updateMember.mutate({ id: editingMemberId, fullName: memberForm.fullName, phone: memberForm.phone || undefined, email: memberForm.email || undefined, joinedAt: dateForApi(memberForm.joinedAt), notes: memberForm.notes || undefined })}>{updateMember.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Pencil className="mr-2 h-4 w-4" />}Enregistrer les modifications</Button> : <Button disabled={addMember.isPending} className="bg-[#285d68] text-white hover:bg-[#214e58]" onClick={() => addMember.mutate({ fullName: memberForm.fullName, phone: memberForm.phone || undefined, email: memberForm.email || undefined, joinedAt: dateForApi(memberForm.joinedAt), notes: memberForm.notes || undefined })}>{addMember.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <UserPlus className="mr-2 h-4 w-4" />}Ajouter</Button>}</DialogFooter></DialogContent></Dialog>

    <Dialog open={paymentOpen} onOpenChange={(open) => { setPaymentOpen(open); if (!open) setPaymentPreviewData(null); }}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>Enregistrer un paiement</DialogTitle><DialogDescription>Chaque versement est enregistré comme une seule entrée financière, puis réparti sur les échéances les plus anciennes.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid gap-4 sm:grid-cols-2"><Field label="Membre"><select className="h-10 w-full rounded-xl border border-[#d8ccba] bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-[#285d68]/20" value={paymentForm.memberId} onChange={(e) => { setPaymentForm({ ...paymentForm, memberId: e.target.value }); setPaymentPreviewData(null); }}><option value="">Sélectionner…</option>{activeMembers.map((member) => <option value={member.memberId} key={member.memberId}>{member.fullName}</option>)}</select></Field><Field label="Montant reçu"><Input type="number" min="1" step="1" value={paymentForm.amount} onChange={(e) => { setPaymentForm({ ...paymentForm, amount: e.target.value }); setPaymentPreviewData(null); }} /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Date réelle"><Input type="date" value={paymentForm.paymentDate} onChange={(e) => { setPaymentForm({ ...paymentForm, paymentDate: e.target.value }); setPaymentPreviewData(null); }} /></Field><Field label="Mode"><select className="h-10 w-full rounded-xl border border-[#d8ccba] bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-[#285d68]/20" value={paymentForm.paymentMethod} onChange={(e) => setPaymentForm({ ...paymentForm, paymentMethod: e.target.value })}>{methods.map((method) => <option key={method}>{method.replace("_", " ")}</option>)}</select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Référence (optionnel)"><Input value={paymentForm.reference} onChange={(e) => setPaymentForm({ ...paymentForm, reference: e.target.value })} /></Field><Field label="Observation"><Input value={paymentForm.observation} onChange={(e) => setPaymentForm({ ...paymentForm, observation: e.target.value })} /></Field></div>{paymentPreviewData && <div className="rounded-2xl bg-[#eff7f0] p-4"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-[#243447]">Aperçu de l’affectation</p><span className="rounded-full bg-white px-2.5 py-1 text-[11px] font-bold text-[#3e7256]">{paymentPreviewData.allocation.length} mois</span></div><p className="mt-1 text-xs text-[#718078]">{paymentPreviewData.memberName} · {currency(Number(paymentForm.amount))}</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{paymentPreviewData.allocation.map((item: any) => <div key={item.monthKey} className="flex items-center justify-between rounded-lg bg-white px-3 py-2 text-xs"><span className="text-[#526a5d]">{item.label}</span><span className="font-semibold text-[#285d68]">{currency(item.amount)}</span></div>)}</div><div className="mt-3 flex items-center gap-2 text-xs font-semibold text-[#3e7256]"><Check className="h-4 w-4" />Les impayés les plus anciens sont prioritaires.</div></div>}</div><DialogFooter><Button variant="outline" onClick={() => setPaymentOpen(false)}>Annuler</Button>{!paymentPreviewData ? <Button onClick={submitPaymentPreview} className="bg-[#285d68] text-white hover:bg-[#214e58]"><Sparkles className="mr-2 h-4 w-4" />Prévisualiser</Button> : <Button disabled={recordPayment.isPending} onClick={confirmPayment} className="bg-[#285d68] text-white hover:bg-[#214e58]">{recordPayment.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Check className="mr-2 h-4 w-4" />}Confirmer le paiement</Button>}</DialogFooter></DialogContent></Dialog>

    <Dialog open={groupOpen} onOpenChange={setGroupOpen}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>Enregistrer les cotisations du mois</DialogTitle><DialogDescription>Sélectionnez les membres ayant payé {currency(data?.contribution)} pour {monthInputLabel(groupForm.month)}.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid gap-4 sm:grid-cols-2"><Field label="Mois"><Input type="month" value={groupForm.month} onChange={(e) => setGroupForm({ ...groupForm, month: e.target.value })} /></Field><Field label="Date réelle"><Input type="date" value={groupForm.paymentDate} onChange={(e) => setGroupForm({ ...groupForm, paymentDate: e.target.value })} /></Field></div><div className="rounded-2xl border border-[#e5ded2] p-3"><div className="mb-2 flex items-center justify-between px-2"><p className="text-xs font-bold uppercase tracking-[0.12em] text-[#789085]">Membres actifs</p><button className="text-xs font-semibold text-[#285d68]" onClick={() => setSelectedGroupMembers(selectedGroupMembers.length === activeMembers.length ? [] : activeMembers.map((member) => member.memberId))}>{selectedGroupMembers.length === activeMembers.length ? "Tout désélectionner" : "Tout sélectionner"}</button></div><div className="grid max-h-64 gap-1 overflow-y-auto">{activeMembers.map((member) => <label key={member.memberId} className="flex items-center gap-3 rounded-xl px-2 py-3 transition hover:bg-[#f5f8f4]"><Checkbox checked={selectedGroupMembers.includes(member.memberId)} onCheckedChange={(checked) => setSelectedGroupMembers(checked ? [...selectedGroupMembers, member.memberId] : selectedGroupMembers.filter((id) => id !== member.memberId))} /><span className="flex-1 text-sm font-medium text-[#345347]">{member.fullName}</span><StatusBadge status={member.status} /></label>)}</div></div></div><DialogFooter><Button variant="outline" onClick={() => setGroupOpen(false)}>Annuler</Button><Button disabled={!selectedGroupMembers.length || recordGroupPayments.isPending} onClick={() => recordGroupPayments.mutate({ month: groupForm.month, memberIds: selectedGroupMembers, paymentDate: dateForApi(groupForm.paymentDate), paymentMethod: groupForm.paymentMethod })} className="bg-[#285d68] text-white hover:bg-[#214e58]">{recordGroupPayments.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Check className="mr-2 h-4 w-4" />}Enregistrer {selectedGroupMembers.length || ""} paiement(s)</Button></DialogFooter></DialogContent></Dialog>

    <Dialog open={withdrawalOpen} onOpenChange={setWithdrawalOpen}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>Enregistrer une sortie</DialogTitle><DialogDescription>Les membres peuvent consulter le motif et le détail de chaque besoin familial.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid gap-4 sm:grid-cols-2"><Field label="Montant"><Input type="number" min="1" value={withdrawalForm.amount} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, amount: e.target.value })} placeholder="25000" /></Field><Field label="Date"><Input type="date" value={withdrawalForm.withdrawalDate} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, withdrawalDate: e.target.value })} /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Catégorie"><select className="h-10 w-full rounded-xl border border-[#d8ccba] bg-white px-3 text-sm" value={withdrawalForm.category} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, category: e.target.value as Category })}>{categories.map((category) => <option key={category}>{category.replaceAll("_", " ")}</option>)}</select></Field><Field label="Personne concernée"><Input value={withdrawalForm.beneficiary} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, beneficiary: e.target.value })} placeholder="Membre ou famille" /></Field></div><Field label="Motif"><Input value={withdrawalForm.motif} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, motif: e.target.value })} placeholder="Assistance médicale" /></Field><Field label="Description"><Textarea value={withdrawalForm.description} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, description: e.target.value })} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Mode de paiement"><select className="h-10 w-full rounded-xl border border-[#d8ccba] bg-white px-3 text-sm" value={withdrawalForm.paymentMethod} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, paymentMethod: e.target.value })}>{methods.map((method) => <option key={method}>{method.replace("_", " ")}</option>)}</select></Field><Field label="Référence"><Input value={withdrawalForm.reference} onChange={(e) => setWithdrawalForm({ ...withdrawalForm, reference: e.target.value })} /></Field></div></div><DialogFooter><Button variant="outline" onClick={() => setWithdrawalOpen(false)}>Annuler</Button><Button disabled={createWithdrawal.isPending} onClick={() => createWithdrawal.mutate({ ...withdrawalForm, amount: Number(withdrawalForm.amount), withdrawalDate: dateForApi(withdrawalForm.withdrawalDate), beneficiary: withdrawalForm.beneficiary || undefined, description: withdrawalForm.description || undefined, reference: withdrawalForm.reference || undefined, observation: withdrawalForm.observation || undefined })} className="bg-[#285d68] text-white hover:bg-[#214e58]">{createWithdrawal.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <ArrowUpRight className="mr-2 h-4 w-4" />}Enregistrer la sortie</Button></DialogFooter></DialogContent></Dialog>

    <Dialog open={announcementOpen} onOpenChange={setAnnouncementOpen}><DialogContent><DialogHeader><DialogTitle>Nouvelle annonce</DialogTitle><DialogDescription>Partagez une information importante avec toute la famille.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><Field label="Titre"><Input value={announcementForm.title} onChange={(e) => setAnnouncementForm({ ...announcementForm, title: e.target.value })} placeholder="Réunion familiale" /></Field><Field label="Message"><Textarea rows={6} value={announcementForm.body} onChange={(e) => setAnnouncementForm({ ...announcementForm, body: e.target.value })} placeholder="Votre message…" /></Field></div><DialogFooter><Button variant="outline" onClick={() => setAnnouncementOpen(false)}>Annuler</Button><Button disabled={createAnnouncement.isPending} onClick={() => createAnnouncement.mutate(announcementForm)} className="bg-[#285d68] text-white hover:bg-[#214e58]"><Megaphone className="mr-2 h-4 w-4" />Publier</Button></DialogFooter></DialogContent></Dialog>
  </>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <div className="grid gap-1.5"><Label className="text-xs font-semibold text-[#526a5d]">{label}</Label>{children}</div>; }

function DashboardPage({ data, period, setPeriod, admin, openPayment, openGroup, openWithdrawal, refreshButton }: { data: any; period: string; setPeriod: (value: string) => void; openPayment: (id?: string) => void; openGroup: () => void; openWithdrawal: () => void; admin: boolean; refreshButton: React.ReactNode }) {
  const summary = data?.summary;
  const progress = summary?.expectedThisMonth ? Math.min(100, Math.round((summary.collectedThisMonth / summary.expectedThisMonth) * 100)) : 0;
  const recent = [...(data?.payments ?? []).slice(0, 4), ...(data?.withdrawals ?? []).slice(0, 2).map((item: any) => ({ ...item, isWithdrawal: true }))].sort((a: any, b: any) => new Date(b.paymentDate ?? b.withdrawalDate).getTime() - new Date(a.paymentDate ?? a.withdrawalDate).getTime()).slice(0, 5);
  return <div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="Vue d’ensemble" title="Bonjour, la caisse avance." description="Un aperçu simple de la solidarité familiale, des cotisations et des besoins du moment." action={<div className="flex items-center gap-2">{refreshButton}<div className="hidden items-center gap-2 rounded-xl border border-[#d8ccba] bg-white px-3 sm:flex"><CalendarDays className="h-4 w-4 text-[#7c9487]" /><input type="month" value={period} onChange={(e) => setPeriod(e.target.value)} className="h-9 bg-transparent text-sm font-semibold text-[#466458] outline-none" /></div></div>} /><div className="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Solde disponible" value={currency(summary?.balance)} meta="Entrées moins sorties" icon={Wallet} tone="lime" /><MetricCard label="Encaissé ce mois" value={currency(summary?.collectedThisMonth)} meta={`${summary?.paidMembersThisMonth ?? 0} membre(s) à jour sur ${summary?.activeMembers ?? 0}`} icon={ArrowDownLeft} tone="mint" /><MetricCard label="En retard" value={currency(summary?.arrears)} meta={`${summary?.lateMembers ?? 0} membre(s) à relancer`} icon={CircleAlert} tone="warm" /><MetricCard label="Avances" value={currency(summary?.advances)} meta={`${summary?.membersWithAdvance ?? 0} membre(s) en avance`} icon={TrendingUp} tone="plain" /></div><div className="grid gap-5 xl:grid-cols-[1.45fr_0.8fr]"><div className="rounded-2xl border border-[#e5ded2] bg-[#285d68] p-6 text-white shadow-[0_20px_60px_-35px_rgba(14,91,73,0.8)] sm:p-7"><div className="flex flex-col justify-between gap-6 sm:flex-row"><div><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#afd6bd]">Objectif de {data?.asOfLabel}</p><p className="mt-3 text-3xl font-semibold tracking-[-0.04em]">{currency(summary?.expectedThisMonth)}</p><p className="mt-2 max-w-md text-sm leading-6 text-[#c7e0d0]">Les versements réels sont comptés une seule fois, même lorsqu’ils couvrent plusieurs mois.</p></div><div className="grid h-16 w-16 shrink-0 place-items-center rounded-2xl bg-[#f2c766] text-[#243447]"><Landmark className="h-7 w-7" /></div></div><div className="mt-8"><div className="mb-2 flex justify-between text-xs font-semibold text-[#c7e0d0]"><span>Progression du mois</span><span>{progress}%</span></div><div className="h-2 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#f2c766] transition-all duration-500" style={{ width: `${progress}%` }} /></div></div>{admin && <div className="mt-7 flex flex-wrap gap-3"><Button onClick={openGroup} className="rounded-xl bg-[#f2c766] text-[#243447] hover:bg-[#e5b553]"><Check className="mr-2 h-4 w-4" />Saisir le mois</Button><Button onClick={() => openPayment()} variant="outline" className="rounded-xl border-white/25 bg-transparent text-white hover:bg-white/10 hover:text-white"><Plus className="mr-2 h-4 w-4" />Paiement individuel</Button></div>}{/* actions admin only */}</div><div className="rounded-2xl border border-[#e5ded2] bg-white p-6"><div className="flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#7c9487]">Répartition</p><h2 className="mt-2 text-lg font-semibold text-[#243447]">État de la famille</h2></div><BarChart3 className="h-5 w-5 text-[#8aa294]" /></div><div className="mt-6 space-y-4">{[["À jour", summary?.upToDateMembers ?? 0, "bg-[#8bc9a1]"], ["En retard", summary?.lateMembers ?? 0, "bg-[#ee9c8d]"], ["Avec avance", summary?.membersWithAdvance ?? 0, "bg-[#f2c766]"]].map(([label, value, color]) => <div key={String(label)}><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium text-[#61756a]">{label}</span><span className="font-bold text-[#243447]">{value}</span></div><div className="h-2 rounded-full bg-[#edf2ed]"><div className={`h-full rounded-full ${color}`} style={{ width: `${summary?.activeMembers ? Math.max(4, (Number(value) / summary.activeMembers) * 100) : 0}%` }} /></div></div>)}</div><div className="mt-7 rounded-xl bg-[#f4f8f3] p-3 text-xs leading-5 text-[#728379]"><span className="font-semibold text-[#3e7256]">Cotisation standard :</span> {currency(data?.contribution)} par membre et par mois.</div></div></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><div className="rounded-2xl border border-[#e5ded2] bg-white p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#7c9487]">Activité récente</p><h2 className="mt-2 text-lg font-semibold text-[#243447]">Dernières opérations</h2></div><ClipboardList className="h-5 w-5 text-[#8aa294]" /></div>{recent.length ? <div className="divide-y divide-[#edf1ed]">{recent.map((item: any, index: number) => <div key={`${item.id}-${index}`} className="flex items-center gap-3 py-3"><div className={`grid h-9 w-9 place-items-center rounded-xl ${item.isWithdrawal ? "bg-[#fff0ef] text-[#b94d43]" : "bg-[#edf3f1] text-[#23734c]"}`}>{item.isWithdrawal ? <ArrowUpRight className="h-4 w-4" /> : <ArrowDownLeft className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#345347]">{item.isWithdrawal ? item.motif : item.memberName}</p><p className="text-xs text-[#8e9696]">{item.isWithdrawal ? item.category : "Cotisation"} · {new Date(item.paymentDate ?? item.withdrawalDate).toLocaleDateString("fr-FR")}</p></div><span className={`text-sm font-bold ${item.isWithdrawal ? "text-[#b94d43]" : "text-[#23734c]"}`}>{item.isWithdrawal ? "−" : "+"}{shortCurrency(item.amount)}</span></div>)}</div> : <EmptyState icon={ClipboardList} title="Pas encore d’opération" body="Les paiements et sorties apparaîtront ici." />}</div><div className="rounded-2xl border border-[#e5ded2] bg-[#fffdf7] p-6"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#aa8c5d]">Action rapide</p><h2 className="mt-2 text-lg font-semibold text-[#4d3b22]">Un besoin familial ?</h2></div><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#ffecc7] text-[#a8752a]"><Sparkles className="h-5 w-5" /></div></div><p className="mt-4 text-sm leading-6 text-[#806d52]">Enregistrez une sortie avec son motif, sa catégorie et la personne concernée. Tout reste visible et traçable.</p>{admin && <Button onClick={openWithdrawal} variant="outline" className="mt-6 w-full rounded-xl border-[#e9d8b8] bg-white text-[#7b5a2d] hover:bg-[#fff6e5]">Enregistrer un besoin <ArrowUpRight className="ml-2 h-4 w-4" /></Button>}</div></div></div>;
}

function MembersPage({ members, search, setSearch, sort, setSort, admin, openPayment, openMember, editMember, deleteMember }: { members: any[]; search: string; setSearch: (value: string) => void; sort: "alpha" | "alphaDesc" | "recent" | "oldest"; setSort: (value: "alpha" | "alphaDesc" | "recent" | "oldest") => void; admin: boolean; openPayment: (id?: string) => void; openMember: () => void; editMember: (member: any) => void; deleteMember: (id: number, name: string) => void }) {
  const orderedMembers = [...members].sort((a, b) => { const alpha = String(a.fullName ?? "").localeCompare(String(b.fullName ?? ""), "fr", { sensitivity: "base" }); if (sort === "alpha") return alpha; if (sort === "alphaDesc") return -alpha; const createdDifference = sortableDate(b.createdAt) - sortableDate(a.createdAt); return sort === "recent" ? (createdDifference || Number(b.recordId ?? b.memberId) - Number(a.recordId ?? a.memberId)) : -createdDifference || Number(a.recordId ?? a.memberId) - Number(b.recordId ?? b.memberId); });
  return <div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="Communauté" title="Les membres" description="Chaque membre peut consulter la situation complète de la caisse. Seul l’administrateur peut modifier les données." action={admin ? <Button onClick={openMember} className="rounded-xl bg-[#285d68] text-white hover:bg-[#214e58]"><UserPlus className="mr-2 h-4 w-4" />Ajouter un membre</Button> : undefined} /><div className="mb-4 flex flex-wrap items-center gap-3"><div className="flex min-w-0 flex-1 items-center gap-3 rounded-xl border border-[#d8ccba] bg-white px-3 sm:max-w-sm"><Search className="h-4 w-4 shrink-0 text-[#8da094]" /><input value={search} onChange={(e) => setSearch(e.target.value)} className="h-10 min-w-0 flex-1 bg-transparent text-sm outline-none" placeholder="Rechercher un membre…" /></div><select value={sort} onChange={(e) => setSort(e.target.value as "alpha" | "alphaDesc" | "recent" | "oldest")} className="h-10 rounded-xl border border-[#d8ccba] bg-white px-3 text-sm text-[#446356] outline-none"><option value="alpha">Croissant (A → Z)</option><option value="alphaDesc">Décroissant (Z → A)</option><option value="recent">Derniers enregistrés</option><option value="oldest">Premiers enregistrés</option></select><span className="rounded-xl bg-[#edf3f1] px-3 py-2 text-xs font-semibold text-[#3e7256]">{orderedMembers.length} membre{orderedMembers.length > 1 ? "s" : ""}</span></div><div className="overflow-hidden rounded-2xl border border-[#e5ded2] bg-white"><div className="hidden grid-cols-[44px_1.5fr_0.8fr_0.8fr_0.8fr_auto] gap-4 border-b border-[#edf1ed] bg-[#f8faf7] px-5 py-3 text-[10px] font-bold uppercase tracking-[0.14em] text-[#8e9696] md:grid"><span>#</span><span>Membre</span><span>Situation</span><span>Payé</span><span>Retard</span><span /></div>{orderedMembers.length ? orderedMembers.map((member, index) => <div key={member.memberId} className="grid gap-3 border-b border-[#edf1ed] px-5 py-4 last:border-0 md:grid-cols-[44px_1.5fr_0.8fr_0.8fr_0.8fr_auto] md:items-center md:gap-4"><div className="text-xs font-bold text-[#8e9696]">{index + 1}</div><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#e7f2e8] text-xs font-bold text-[#285d68]">{initials(member.fullName)}</div><div><p className="text-sm font-semibold text-[#345347]">{member.fullName}</p><p className="text-xs text-[#8e9696]">{member.phone || "Aucun téléphone"} · {member.isActive ? "Actif" : "Inactif"}</p></div></div><div><span className="mr-2 text-[10px] text-[#9aaa9f] md:hidden">Situation ·</span><StatusBadge status={member.status} /></div><div className="text-sm font-semibold text-[#4b6558]"><span className="mr-2 text-[10px] font-normal text-[#9aaa9f] md:hidden">Payé ·</span>{member.paidMonths} mois</div><div className="text-sm font-semibold text-[#b94d43]"><span className="mr-2 text-[10px] font-normal text-[#9aaa9f] md:hidden">Retard ·</span>{currency(member.dueAmount)}</div><div className="flex flex-wrap gap-2">{admin && <Button onClick={() => editMember(member)} variant="outline" className="h-9 rounded-lg border-[#cfe0d2] bg-white px-2 text-xs text-[#285d68] hover:bg-[#eef7ef]"><Pencil className="mr-1 h-3.5 w-3.5" />Modifier</Button>}{admin && <Button onClick={() => deleteMember(member.memberId, member.fullName)} variant="outline" className="h-9 rounded-lg border-[#f0d2cf] bg-white px-2 text-xs text-[#b94d43] hover:bg-[#fff5f4]">Supprimer</Button>}{admin && member.isActive && <Button onClick={() => openPayment(member.memberId)} variant="outline" className="h-9 rounded-lg border-[#cfe0d2] bg-white px-2 text-xs text-[#285d68] hover:bg-[#eef7ef]">Enregistrer</Button>}</div></div>) : <div className="p-10"><EmptyState icon={Users} title="Aucun membre trouvé" body="Ajoutez un membre ou modifiez votre recherche." /></div>}</div></div>;
}

function ContributionsPage({ data, period, setPeriod, admin, openPayment, openGroup, editPayment, deletePayment }: { data: any; period: string; setPeriod: (value: string) => void; admin: boolean; openPayment: (id?: string) => void; openGroup: () => void; editPayment: (payment: any) => void; deletePayment: (id: number, name: string, amount: number) => void }) {
  const [sort, setSort] = useState<"alpha" | "recent" | "oldest">("alpha");
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const members = (data?.members ?? []).filter((member: any) => member.isActive);
  const ordered = [...members].sort((a: any, b: any) => sort === "alpha" ? String(a.fullName ?? "").localeCompare(String(b.fullName ?? ""), "fr", { sensitivity: "base" }) : sort === "recent" ? sortableDate(b.joinedAt) - sortableDate(a.joinedAt) : sortableDate(a.joinedAt) - sortableDate(b.joinedAt));
  const pageCount = Math.max(1, Math.ceil(ordered.length / pageSize));
  const visible = ordered.slice((page - 1) * pageSize, page * pageSize);
  return <div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="Suivi mensuel" title="Cotisations" description="Les échéances sont calculées automatiquement. Les avances et rattrapages restent liés au paiement réel." action={<div className="flex flex-wrap gap-2">{admin && <><Button onClick={openGroup} className="rounded-xl bg-[#285d68] text-white hover:bg-[#214e58]"><Check className="mr-2 h-4 w-4" />Saisir le mois</Button><Button onClick={() => openPayment()} variant="outline" className="rounded-xl border-[#cfe0d2] bg-white text-[#285d68]"><Plus className="mr-2 h-4 w-4" />Paiement individuel</Button></>}</div>} /><div className="mb-5 flex flex-wrap items-center gap-3"><div className="flex items-center gap-2 rounded-xl border border-[#d8ccba] bg-white px-3"><CalendarDays className="h-4 w-4 text-[#7c9487]" /><input type="month" value={period} onChange={(e) => { setPeriod(e.target.value); setPage(1); }} className="h-10 bg-transparent text-sm font-semibold text-[#466458] outline-none" /></div><select value={sort} onChange={(e) => { setSort(e.target.value as any); setPage(1); }} className="h-10 rounded-xl border border-[#d8ccba] bg-white px-3 text-sm text-[#446356]"><option value="alpha">A → Z</option><option value="recent">Membres récents</option><option value="oldest">Membres anciens</option></select><span className="rounded-xl bg-[#edf3f1] px-3 py-2 text-xs font-semibold text-[#3e7256]">{ordered.length} membre{ordered.length > 1 ? "s" : ""}</span><div className="rounded-xl bg-[#edf3f1] px-3 py-2 text-xs font-semibold text-[#3e7256]">Cotisation : {currency(data?.contribution)}</div></div><div className="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Prévu" value={currency(data?.summary.expectedThisMonth)} meta={`${data?.summary.activeMembers ?? 0} membres actifs`} icon={Receipt} /><MetricCard label="Encaissé" value={currency(data?.summary.collectedThisMonth)} meta={`${data?.summary.paidMembersThisMonth ?? 0} paiements complets`} icon={ArrowDownLeft} tone="mint" /><MetricCard label="Impayés" value={currency(data?.summary.arrears)} meta={`${data?.summary.unpaidMembersThisMonth ?? 0} membre(s) à relancer`} icon={CircleAlert} tone="warm" /><MetricCard label="Avances" value={currency(data?.summary.advances)} meta="Réparties sur les échéances futures" icon={TrendingUp} tone="lime" /></div><div className="overflow-hidden rounded-2xl border border-[#e5ded2] bg-white"><div className="border-b border-[#edf1ed] bg-[#f8faf7] px-5 py-4"><p className="text-[11px] font-bold uppercase tracking-[0.14em] text-[#7c9487]">Situation au {data?.asOfLabel}</p></div>{visible.length ? visible.map((member: any, index: number) => <div key={member.memberId} className="grid gap-3 border-b border-[#edf1ed] px-5 py-4 last:border-0 md:grid-cols-[44px_1.6fr_0.75fr_0.75fr_0.8fr_auto] md:items-center"><div className="text-xs font-bold text-[#8e9696]">{(page - 1) * pageSize + index + 1}</div><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#e7f2e8] text-xs font-bold text-[#285d68]">{initials(member.fullName)}</div><div><p className="text-sm font-semibold text-[#345347]">{member.fullName}</p><p className="text-xs text-[#8e9696]">{member.upToMonth ? `À jour jusqu’à ${monthInputLabel(member.upToMonth)}` : "Aucune échéance payée"}</p></div></div><div className="text-sm font-semibold text-[#496356]">{member.paidMonths} mois</div><div className="text-sm font-semibold text-[#b94d43]">{member.lateMonths}</div><div><StatusBadge status={member.status} /></div>{admin && <Button onClick={() => openPayment(member.memberId)} variant="outline" className="h-9 rounded-lg border-[#cfe0d2] text-xs text-[#285d68]">Saisir</Button>}</div>) : <div className="p-10"><EmptyState icon={Users} title="Aucun membre" body="Aucun membre actif à afficher." /></div>}</div><div className="mt-4 flex items-center justify-between text-xs text-[#718078]"><span>Page {Math.min(page, pageCount)} sur {pageCount}</span><div className="flex gap-2"><Button variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="h-8 rounded-lg px-3 text-xs">Précédent</Button><Button variant="outline" disabled={page >= pageCount} onClick={() => setPage((value) => value + 1)} className="h-8 rounded-lg px-3 text-xs">Suivant</Button></div></div></div>;
}

function CashPage({ data, admin, openWithdrawal, deleteWithdrawal }: { data: any; admin: boolean; openWithdrawal: () => void; deleteWithdrawal: (id: number) => void }) {
  const [sort, setSort] = useState<"alpha" | "alphaDesc" | "recent" | "oldest">("recent");
  const [period, setPeriod] = useState<"all" | "month" | "year">("all");
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const filtered = (data?.withdrawals ?? []).filter((item: any) => {
    const date = new Date(sortableDate(item.withdrawalDate ?? item.withdrawal_date));
    const now = new Date();
    return period === "all" || (period === "month" && date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth()) || (period === "year" && date.getFullYear() === now.getFullYear());
  });
  const ordered = [...filtered].sort((a: any, b: any) => { const alpha = String(a.motif ?? "").localeCompare(String(b.motif ?? ""), "fr", { sensitivity: "base" }); if (sort === "alpha") return alpha; if (sort === "alphaDesc") return -alpha; const createdDifference = recordTimestamp(b) - recordTimestamp(a); return sort === "recent" ? (createdDifference || Number(b.id ?? 0) - Number(a.id ?? 0)) : -createdDifference || Number(a.id ?? 0) - Number(b.id ?? 0); });
  const pageCount = Math.max(1, Math.ceil(ordered.length / pageSize));
  const visible = ordered.slice((page - 1) * pageSize, page * pageSize);
  const changePeriod = (value: "all" | "month" | "year") => { setPeriod(value); setPage(1); };
  return <div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="Transparence financière" title="La caisse commune" description="Une cotisation réelle = une entrée. Les sorties sont documentées et visibles par tous les membres." action={admin ? <Button onClick={openWithdrawal} className="rounded-xl bg-[#285d68] text-white hover:bg-[#214e58]"><ArrowUpRight className="mr-2 h-4 w-4" />Enregistrer une sortie</Button> : undefined} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><MetricCard label="Solde disponible" value={currency(data?.summary.balance)} meta="Le montant mobilisable" icon={Wallet} tone="lime" /><MetricCard label="Total des entrées" value={currency(data?.summary.totalIn)} meta="Paiements réels reçus" icon={ArrowDownLeft} tone="mint" /><MetricCard label="Total des sorties" value={currency(data?.summary.totalOut)} meta="Besoins familiaux enregistrés" icon={ArrowUpRight} tone="warm" /></div><div className="rounded-2xl border border-[#e5ded2] bg-white p-6"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#7c9487]">Mouvements</p><h2 className="mt-2 text-lg font-semibold text-[#243447]">Entrées et sorties</h2></div><div className="flex flex-wrap items-center gap-2"><select value={period} onChange={(e) => changePeriod(e.target.value as any)} className="h-9 rounded-lg border border-[#d8ccba] bg-white px-2 text-xs text-[#446356]"><option value="all">Toutes les périodes</option><option value="month">Ce mois-ci</option><option value="year">Cette année</option></select><select value={sort} onChange={(e) => { setSort(e.target.value as any); setPage(1); }} className="h-9 rounded-lg border border-[#d8ccba] bg-white px-2 text-xs text-[#446356]"><option value="recent">Dernières enregistrées</option><option value="oldest">Premières enregistrées</option><option value="alpha">Croissant (A → Z)</option><option value="alphaDesc">Décroissant (Z → A)</option></select><span className="rounded-lg bg-[#edf3f1] px-2.5 py-1.5 text-xs font-semibold text-[#3e7256]">{ordered.length} opération{ordered.length > 1 ? "s" : ""}</span></div></div>{visible.length ? <div className="divide-y divide-[#edf1ed]">{visible.map((item: any, index: number) => <div key={item.id} className="flex flex-wrap items-center gap-3 py-4"><span className="w-7 text-xs font-bold text-[#8e9696]">{(page - 1) * pageSize + index + 1}</span><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#fff0ef] text-[#b94d43]"><ArrowUpRight className="h-4 w-4" /></div><div className="min-w-[180px] flex-1"><p className="text-sm font-semibold text-[#345347]">{item.motif}</p><p className="text-xs text-[#8e9696]">{item.category.replaceAll("_", " ")} · {item.beneficiary || "Famille"} · {new Date(item.withdrawalDate ?? item.withdrawal_date).toLocaleDateString("fr-FR")}</p></div><span className="text-sm font-bold text-[#b94d43]">−{currency(item.amount)}</span>{admin && <Button onClick={() => deleteWithdrawal(item.id)} variant="outline" className="h-8 rounded-lg border-[#f0d2cf] bg-white px-2 text-xs text-[#b94d43] hover:bg-[#fff5f4]">Supprimer</Button>}</div>)}</div> : <EmptyState icon={Landmark} title="Aucune opération" body="Aucune sortie ne correspond aux filtres sélectionnés." />}<div className="mt-5 flex items-center justify-between border-t border-[#edf1ed] pt-4 text-xs text-[#718078]"><span>Page {Math.min(page, pageCount)} sur {pageCount}</span><div className="flex gap-2"><Button variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="h-8 rounded-lg px-3 text-xs">Précédent</Button><Button variant="outline" disabled={page >= pageCount} onClick={() => setPage((value) => value + 1)} className="h-8 rounded-lg px-3 text-xs">Suivant</Button></div></div></div></div>;
}

function HistoryPage({ data, admin, editPayment, bulkDeletePayments, bulkUpdatePayments, deletePayment }: { data: any; admin: boolean; editPayment: (payment: any) => void; bulkDeletePayments: (ids: number[]) => Promise<void>; bulkUpdatePayments: (ids: number[], amount: number) => Promise<void>; deletePayment: (id: number, name: string, amount: number) => void }) {
  const [selected, setSelected] = useState<number[]>([]);
  const [sort, setSort] = useState<"alpha" | "alphaDesc" | "recent" | "oldest">("recent");
  const [period, setPeriod] = useState<"all" | "month" | "year">("all");
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const filtered = (data?.payments ?? []).filter((item: any) => {
    const date = new Date(sortableDate(item.paymentDate ?? item.payment_date));
    const now = new Date();
    return period === "all" || (period === "month" && date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth()) || (period === "year" && date.getFullYear() === now.getFullYear());
  });
  const ordered = [...filtered].sort((a: any, b: any) => { const alpha = String(a.memberName ?? "").localeCompare(String(b.memberName ?? ""), "fr", { sensitivity: "base" }); if (sort === "alpha") return alpha; if (sort === "alphaDesc") return -alpha; const createdDifference = recordTimestamp(b) - recordTimestamp(a); return sort === "recent" ? (createdDifference || Number(b.id ?? 0) - Number(a.id ?? 0)) : -createdDifference || Number(a.id ?? 0) - Number(b.id ?? 0); });
  const pageCount = Math.max(1, Math.ceil(ordered.length / pageSize));
  const visible = ordered.slice((page - 1) * pageSize, page * pageSize);
  const toggleSelected = (id: number) => setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const selectAll = () => { const allIds = ordered.map((item: any) => Number(item.id)); setSelected((current) => current.length === allIds.length && allIds.every((id) => current.includes(id)) ? [] : allIds); };
  const bulkDelete = async () => { if (!selected.length || !window.confirm(`Annuler définitivement ${selected.length} paiement(s) sélectionné(s) ?`)) return; await bulkDeletePayments(selected); setSelected([]); };
  const bulkEdit = async () => { if (!selected.length) return; const value = window.prompt(`Nouveau montant à appliquer aux ${selected.length} paiements sélectionnés (FCFA) :`); if (value === null) return; const amount = Number(value); if (!Number.isFinite(amount) || amount <= 0) { toast.error("Le montant doit être positif."); return; } await bulkUpdatePayments(selected, amount); setSelected([]); };
  return <div className="mx-auto max-w-[1200px]"><SectionHeading eyebrow="Traçabilité" title="Historique des paiements" description="Chaque paiement conserve sa date réelle, son montant, son mode, sa référence et le détail des mois couverts." /><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div className="flex flex-wrap gap-2"><select value={period} onChange={(e) => { setPeriod(e.target.value as any); setPage(1); }} className="h-9 rounded-lg border border-[#d8ccba] bg-white px-2 text-xs text-[#446356]"><option value="all">Toutes les périodes</option><option value="month">Ce mois-ci</option><option value="year">Cette année</option></select><select value={sort} onChange={(e) => { setSort(e.target.value as any); setPage(1); }} className="h-9 rounded-lg border border-[#d8ccba] bg-white px-2 text-xs text-[#446356]"><option value="recent">Derniers enregistrés</option><option value="oldest">Premiers enregistrés</option><option value="alpha">Croissant (A → Z)</option><option value="alphaDesc">Décroissant (Z → A)</option></select></div><span className="rounded-lg bg-[#edf3f1] px-2.5 py-1.5 text-xs font-semibold text-[#3e7256]">{ordered.length} paiement{ordered.length > 1 ? "s" : ""}</span>{admin && <div className="flex flex-wrap gap-2"><Button onClick={selectAll} variant="outline" className="h-9 rounded-lg px-3 text-xs">{selected.length === ordered.length && ordered.length ? "Désélectionner tout" : "Tout sélectionner"}</Button><Button onClick={bulkEdit} disabled={!selected.length} variant="outline" className="h-9 rounded-lg border-[#d8ccba] px-3 text-xs text-[#285d68]">Modifier le montant{selected.length ? ` (${selected.length})` : ""}</Button><Button onClick={bulkDelete} disabled={!selected.length} variant="outline" className="h-9 rounded-lg border-[#f0d2cf] px-3 text-xs text-[#b65b48]">Annuler / supprimer{selected.length ? ` (${selected.length})` : ""}</Button></div>}</div>{visible.length ? <div className="space-y-3">{visible.map((payment: any, index: number) => { const allocations = (data.allocations ?? []).filter((item: any) => item.paymentTransactionId === payment.id); return <div key={payment.id} className="rounded-2xl border border-[#e5ded2] bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-center gap-3">{admin && <Checkbox checked={selected.includes(Number(payment.id))} onCheckedChange={() => toggleSelected(Number(payment.id))} aria-label={`Sélectionner le paiement ${payment.id}`} />}<span className="w-7 text-xs font-bold text-[#8e9696]">{(page - 1) * pageSize + index + 1}</span><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf3f1] text-[#23734c]"><Receipt className="h-5 w-5" /></div><div><p className="text-sm font-semibold text-[#345347]">{payment.memberName}</p><p className="text-xs text-[#8e9696]">Paiement #{String(payment.id).padStart(5, "0")} · {new Date(payment.paymentDate ?? payment.payment_date).toLocaleDateString("fr-FR")} · {String(payment.paymentMethod ?? payment.payment_method ?? "").replace("_", " ")}</p></div></div><p className="text-lg font-bold text-[#23734c]">+{currency(payment.amount)}</p></div><div className="mt-4 flex flex-wrap gap-2">{allocations.map((allocation: any) => <span key={allocation.id} className="rounded-lg bg-[#f1f7f0] px-2.5 py-1.5 text-xs font-medium text-[#4c715c]">{monthInputLabel(allocation.monthKey ?? allocation.month_key)} · {currency(allocation.amount ?? allocation.allocated_amount)}</span>)}</div>{payment.reference && <p className="mt-3 text-xs text-[#8e9696]">Réf. {payment.reference}</p>}{admin && <div className="mt-4 flex justify-end border-t border-[#f0ebe3] pt-3"><Button onClick={() => editPayment(payment)} variant="outline" className="h-9 rounded-lg border-[#d8ccba] bg-white px-3 text-xs text-[#285d68] hover:bg-[#edf3f1]"><Pencil className="mr-1.5 h-3.5 w-3.5" />Modifier</Button><Button onClick={() => deletePayment(payment.id, payment.memberName, Number(payment.amount))} variant="outline" className="h-9 rounded-lg border-[#f0d2cf] bg-white px-3 text-xs text-[#b65b48] hover:bg-[#fff5f4]"><Trash2 className="mr-1.5 h-3.5 w-3.5" />Annuler / supprimer</Button></div>}</div>; })}</div> : <EmptyState icon={Receipt} title="Aucun paiement" body="Aucun paiement ne correspond aux filtres sélectionnés." />}<div className="mt-5 flex items-center justify-between border-t border-[#edf1ed] pt-4 text-xs text-[#718078]"><span>Page {Math.min(page, pageCount)} sur {pageCount}</span><div className="flex gap-2"><Button variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="h-8 rounded-lg px-3 text-xs">Précédent</Button><Button variant="outline" disabled={page >= pageCount} onClick={() => setPage((value) => value + 1)} className="h-8 rounded-lg px-3 text-xs">Suivant</Button></div></div></div>;
}

function ReportsPage({ data }: { data: any }) { const summary = data?.summary; return <div className="mx-auto max-w-[1100px]"><SectionHeading eyebrow="Synthèse partageable" title={`Rapport de ${data?.asOfLabel ?? "ce mois"}`} description="Une lecture claire du mois, prête à être imprimée ou exportée depuis votre navigateur." action={<Button onClick={() => window.print()} variant="outline" className="rounded-xl border-[#cfe0d2] bg-white text-[#285d68]"><Download className="mr-2 h-4 w-4" />Imprimer / PDF</Button>} /><div className="rounded-3xl border border-[#e5ded2] bg-white p-6 shadow-[0_16px_50px_-38px_rgba(18,66,52,0.5)] sm:p-10"><div className="flex flex-wrap items-start justify-between gap-5 border-b border-[#edf1ed] pb-7"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#285d68]">Caisse Familiale</p><h2 className="mt-3 text-3xl font-semibold tracking-[-0.04em] text-[#243447]">Rapport mensuel</h2><p className="mt-1 text-sm text-[#7b8589]">{data?.asOfLabel}</p></div><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#f2c766] text-[#243447]"><FileText className="h-6 w-6" /></div></div><div className="my-8 grid gap-6 sm:grid-cols-2"><ReportLine label="Membres actifs" value={String(summary?.activeMembers ?? 0)} /><ReportLine label="Cotisation prévue" value={currency(summary?.expectedThisMonth)} /><ReportLine label="Montant encaissé" value={currency(summary?.collectedThisMonth)} /><ReportLine label="Membres ayant payé" value={String(summary?.paidMembersThisMonth ?? 0)} /><ReportLine label="Membres en retard" value={String(summary?.lateMembers ?? 0)} /><ReportLine label="Avances de cotisation" value={currency(summary?.advances)} /></div><div className="grid gap-4 rounded-2xl bg-[#285d68] p-5 text-white sm:grid-cols-3"><div><p className="text-xs text-[#b8dac4]">Total des entrées</p><p className="mt-2 text-xl font-semibold">{currency(summary?.totalIn)}</p></div><div><p className="text-xs text-[#b8dac4]">Total des sorties</p><p className="mt-2 text-xl font-semibold">{currency(summary?.totalOut)}</p></div><div><p className="text-xs text-[#b8dac4]">Solde</p><p className="mt-2 text-xl font-semibold text-[#f2c766]">{currency(summary?.balance)}</p></div></div></div></div>; }
function ReportLine({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between border-b border-[#edf1ed] pb-3"><span className="text-sm text-[#718078]">{label}</span><span className="text-sm font-semibold text-[#345347]">{value}</span></div>; }


function StatusPage({ data }: { data: any }) {
  const [status, setStatus] = useState<"ALL" | "RETARD" | "A_JOUR" | "AVANCE">("ALL");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const members = (data?.members ?? []).filter((member: any) => member.isActive && (status === "ALL" || member.status === status) && String(member.fullName ?? "").toLocaleLowerCase("fr").includes(search.toLocaleLowerCase("fr")));
  const pageCount = Math.max(1, Math.ceil(members.length / pageSize));
  const visible = members.slice((page - 1) * pageSize, page * pageSize);
  const counts = { RETARD: (data?.members ?? []).filter((m: any) => m.isActive && m.status === "RETARD").length, A_JOUR: (data?.members ?? []).filter((m: any) => m.isActive && m.status === "A_JOUR").length, AVANCE: (data?.members ?? []).filter((m: any) => m.isActive && m.status === "AVANCE").length };
  return <div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="Suivi familial" title="Situations des membres" description="Consultez les personnes en retard, à jour ou en avance avec les détails de leurs cotisations." /><div className="grid gap-3 sm:grid-cols-3"><button onClick={() => { setStatus("RETARD"); setPage(1); }} className={`rounded-2xl border p-4 text-left transition ${status === "RETARD" ? "border-[#e58b70] bg-[#fff1ec]" : "border-[#e5ded2] bg-white"}`}><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#b65b48]">En retard</p><p className="mt-2 text-2xl font-semibold text-[#243447]">{counts.RETARD}</p><p className="text-xs text-[#8e9696]">personne(s) à relancer</p></button><button onClick={() => { setStatus("A_JOUR"); setPage(1); }} className={`rounded-2xl border p-4 text-left transition ${status === "A_JOUR" ? "border-[#9cc9a5] bg-[#edf7ef]" : "border-[#e5ded2] bg-white"}`}><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#3f7950]">À jour</p><p className="mt-2 text-2xl font-semibold text-[#243447]">{counts.A_JOUR}</p><p className="text-xs text-[#8e9696]">situation régulière</p></button><button onClick={() => { setStatus("AVANCE"); setPage(1); }} className={`rounded-2xl border p-4 text-left transition ${status === "AVANCE" ? "border-[#e5b553] bg-[#fff8e7]" : "border-[#e5ded2] bg-white"}`}><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#a8752a]">En avance</p><p className="mt-2 text-2xl font-semibold text-[#243447]">{counts.AVANCE}</p><p className="text-xs text-[#8e9696]">mois anticipés</p></button></div><div className="mt-5 flex flex-wrap items-center gap-3"><div className="flex min-w-0 flex-1 items-center gap-3 rounded-xl border border-[#d8ccba] bg-white px-3 sm:max-w-sm"><Search className="h-4 w-4 shrink-0 text-[#8e9696]" /><input value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} className="h-10 min-w-0 flex-1 bg-transparent text-sm outline-none" placeholder="Rechercher une personne…" /></div><select value={status} onChange={(e) => { setStatus(e.target.value as any); setPage(1); }} className="h-10 rounded-xl border border-[#d8ccba] bg-white px-3 text-sm text-[#63747a]"><option value="ALL">Toutes les situations</option><option value="RETARD">En retard</option><option value="A_JOUR">À jour</option><option value="AVANCE">En avance</option></select><span className="rounded-xl bg-[#edf3f1] px-3 py-2 text-xs font-semibold text-[#285d68]">{members.length} personne{members.length > 1 ? "s" : ""}</span></div><div className="mt-4 space-y-3">{visible.length ? visible.map((member: any, index: number) => <div key={member.memberId} className="rounded-2xl border border-[#e5ded2] bg-white p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf3f1] text-xs font-bold text-[#285d68]">{initials(member.fullName)}</div><div><p className="font-semibold text-[#243447]">{member.fullName}</p><p className="text-xs text-[#8e9696]">{member.phone || "Aucun téléphone"} · Membre n°{(page - 1) * pageSize + index + 1}</p></div></div><StatusBadge status={member.status} /></div><div className="mt-4 grid gap-3 border-t border-[#f0ebe3] pt-4 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><p className="text-xs text-[#8e9696]">Cotisations payées</p><p className="font-semibold text-[#243447]">{member.paidMonths} mois · {currency(member.paidAmount)}</p></div><div><p className="text-xs text-[#8e9696]">Retard à régulariser</p><p className="font-semibold text-[#b65b48]">{member.lateMonths} mois · {currency(member.dueAmount)}</p></div><div><p className="text-xs text-[#8e9696]">Avance disponible</p><p className="font-semibold text-[#a8752a]">{member.advanceMonths} mois</p></div><div><p className="text-xs text-[#8e9696]">Dernier mois couvert</p><p className="font-semibold text-[#285d68]">{member.upToMonth ? monthInputLabel(member.upToMonth) : "Aucun"}</p></div></div></div>) : <EmptyState icon={Users} title="Aucun membre dans cette catégorie" body="Modifiez le filtre ou la recherche pour afficher une autre situation." />}</div><div className="mt-5 flex items-center justify-between text-xs text-[#718078]"><span>Page {Math.min(page, pageCount)} sur {pageCount}</span><div className="flex gap-2"><Button variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="h-8 rounded-lg px-3 text-xs">Précédent</Button><Button variant="outline" disabled={page >= pageCount} onClick={() => setPage((value) => value + 1)} className="h-8 rounded-lg px-3 text-xs">Suivant</Button></div></div></div>;
}

function StatisticsPage({ data }: { data: any }) { const summary = data?.summary; const max = Math.max(summary?.activeMembers || 1, 1); const bars = [{ label: "À jour", value: summary?.upToDateMembers ?? 0, color: "bg-[#8bc9a1]" }, { label: "Retard", value: summary?.lateMembers ?? 0, color: "bg-[#ee9c8d]" }, { label: "Avance", value: summary?.membersWithAdvance ?? 0, color: "bg-[#f2c766]" }]; return <div className="mx-auto max-w-[1100px]"><SectionHeading eyebrow="Lecture de la caisse" title="Statistiques" description="Les indicateurs restent lisibles pour tous les membres, sans masquer les retards ni les avances." /><div className="grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-[#e5ded2] bg-white p-6"><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#7c9487]">Répartition des membres</p><h2 className="mt-2 text-lg font-semibold text-[#243447]">Situation actuelle</h2><div className="mt-8 space-y-5">{bars.map((bar) => <div key={bar.label}><div className="mb-2 flex justify-between text-sm"><span className="text-[#61756a]">{bar.label}</span><span className="font-bold text-[#243447]">{bar.value}</span></div><div className="h-4 rounded-full bg-[#edf2ed]"><div className={`h-full rounded-full ${bar.color} transition-all`} style={{ width: `${(bar.value / max) * 100}%` }} /></div></div>)}</div></div><div className="rounded-2xl border border-[#e5ded2] bg-[#285d68] p-6 text-white"><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#afd6bd]">Santé financière</p><h2 className="mt-2 text-lg font-semibold">Les chiffres clés</h2><div className="mt-6 grid gap-4 sm:grid-cols-2"><StatBox label="Taux de paiement" value={`${summary?.activeMembers ? Math.round((summary.paidMembersThisMonth / summary.activeMembers) * 100) : 0}%`} /><StatBox label="Avances" value={currency(summary?.advances)} /><StatBox label="Entrées cumulées" value={currency(summary?.totalIn)} /><StatBox label="Solde actuel" value={currency(summary?.balance)} /></div></div></div></div>; }
function StatBox({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-white/10 p-4"><p className="text-xs text-[#b8dac4]">{label}</p><p className="mt-2 text-lg font-semibold text-[#f2c766]">{value}</p></div>; }

function AnnouncementsPage({ data, admin, openAnnouncement }: { data: any; admin: boolean; openAnnouncement: () => void }) { return <div className="mx-auto max-w-[1000px]"><SectionHeading eyebrow="Vie du groupe" title="Annonces familiales" description="Les informations importantes restent accessibles à toute la famille." action={admin ? <Button onClick={openAnnouncement} className="rounded-xl bg-[#285d68] text-white hover:bg-[#214e58]"><Megaphone className="mr-2 h-4 w-4" />Nouvelle annonce</Button> : undefined} />{(data?.announcements ?? []).length ? <div className="grid gap-4 sm:grid-cols-2">{data.announcements.map((announcement: any) => <article key={announcement.id} className="rounded-2xl border border-[#e5ded2] bg-white p-6"><div className="flex items-start justify-between gap-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#fff2d5] text-[#a8752a]"><Megaphone className="h-5 w-5" /></div><span className="text-xs text-[#8e9696]">{new Date(announcement.publishedAt).toLocaleDateString("fr-FR")}</span></div><h2 className="mt-5 text-lg font-semibold text-[#243447]">{announcement.title}</h2><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[#718078]">{announcement.body}</p></article>)}</div> : <EmptyState icon={Megaphone} title="Aucune annonce" body="Les nouvelles importantes partagées par l’administrateur apparaîtront ici." />}</div>; }
function AuditPage({ data }: { data: any }) { return <div className="mx-auto max-w-[1200px]"><SectionHeading eyebrow="Confiance et traçabilité" title="Journal d’audit" description="Chaque création, modification, suppression, paiement et retrait laisse une trace consultable." /><div className="overflow-hidden rounded-2xl border border-[#e5ded2] bg-white">{(data?.auditLogs ?? []).length ? <div className="divide-y divide-[#edf1ed]">{data.auditLogs.map((log: any) => <div key={log.id} className="flex items-center gap-4 px-5 py-4"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#eef4ef] text-[#285d68]"><ShieldCheck className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#345347]">{log.action} · {log.entityType}</p><p className="text-xs text-[#8e9696]">Utilisateur #{log.userId} · {new Date(log.createdAt).toLocaleString("fr-FR")}</p></div><span className="hidden rounded-full bg-[#f4f7f3] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-[#718078] sm:inline-flex">Journalisé</span></div>)}</div> : <EmptyState icon={ShieldCheck} title="Le journal est vierge" body="Les opérations importantes seront journalisées automatiquement." />}</div></div>; }
function SettingsPage({ data, admin, draft, setDraft, save }: { data: any; admin: boolean; draft: string; setDraft: (value: string) => void; save: () => void }) { return <div className="mx-auto max-w-[760px]"><SectionHeading eyebrow="Configuration" title="Paramètres" description="Les règles de la caisse sont centralisées ici. Les membres peuvent les consulter, seul l’administrateur peut les modifier." /><div className="rounded-2xl border border-[#e5ded2] bg-white p-6 sm:p-8"><div className="flex items-start gap-4"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-[#f2c766] text-[#243447]"><Wallet className="h-5 w-5" /></div><div><h2 className="text-lg font-semibold text-[#243447]">Cotisation mensuelle standard</h2><p className="mt-1 text-sm leading-6 text-[#718078]">Cette valeur sert à calculer automatiquement les échéances, les avances et les rattrapages.</p></div></div><div className="mt-7 max-w-sm"><Field label="Montant par membre et par mois"><div className="flex items-center gap-2"><Input type="number" min="1" value={draft} disabled={!admin} onChange={(e) => setDraft(e.target.value)} /><span className="text-sm font-semibold text-[#7b8589]">FCFA</span></div></Field>{admin ? <Button onClick={save} className="mt-4 rounded-xl bg-[#285d68] text-white hover:bg-[#214e58]">Enregistrer la règle</Button> : <p className="mt-4 text-xs font-medium text-[#7d8f84]">Mode lecture seule — votre rôle de membre ne permet pas de modifier les paramètres.</p>}</div></div><div className="mt-5 rounded-2xl border border-[#e5ded2] bg-[#f8faf7] p-6"><p className="text-[11px] font-bold uppercase tracking-[0.15em] text-[#7c9487]">Règles actives</p><div className="mt-4 grid gap-3 text-sm text-[#526a5d]"><p className="flex items-center gap-2"><Check className="h-4 w-4 text-[#3e925c]" />Impayés les plus anciens affectés en priorité</p><p className="flex items-center gap-2"><Check className="h-4 w-4 text-[#3e925c]" />Une seule entrée financière par paiement réel</p><p className="flex items-center gap-2"><Check className="h-4 w-4 text-[#3e925c]" />Aucune distribution automatique ni système de tours</p></div></div></div>; }
